-- =========================================================================
-- SCRIPT INICIAL MYSQL 8.0 - GRUPO 4 (MODELO CORREGIDO 18 TABLAS)
-- =========================================================================
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS test_conexion;
DROP TABLE IF EXISTS ABARCA;
DROP TABLE IF EXISTS ASIGNA_AYUDANTE;
DROP TABLE IF EXISTS CONDUCE;
DROP TABLE IF EXISTS E_LIM_RUTA;
DROP TABLE IF EXISTS VEHICULO;
DROP TABLE IF EXISTS CENTRO_DESTINO;
DROP TABLE IF EXISTS ENTREGA;
DROP TABLE IF EXISTS INSUMO;
DROP TABLE IF EXISTS AYUDANTE;
DROP TABLE IF EXISTS CONDUCTOR;
DROP TABLE IF EXISTS LIMPIADOR;
DROP TABLE IF EXISTS EMPLEADO;
DROP TABLE IF EXISTS CONTENEDOR;
DROP TABLE IF EXISTS E_ZONA_RUTA;
DROP TABLE IF EXISTS RUTA;
DROP TABLE IF EXISTS ZONA_DISTRITO;
DROP TABLE IF EXISTS ZONA;
DROP TABLE IF EXISTS DISTRITO;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE DISTRITO (
  id_distrito   INT          NOT NULL,
  nombre        VARCHAR(60)  NOT NULL,
  descripcion   VARCHAR(200),
  PRIMARY KEY (id_distrito)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ZONA (
  id_zona       INT          NOT NULL,
  nombre        VARCHAR(60)  NOT NULL,
  topografia    VARCHAR(30),
  PRIMARY KEY (id_zona),
  CONSTRAINT ck_zona_topo CHECK (topografia IN ('PLANA','PENDIENTE SUAVE','PENDIENTE MODERADA','PENDIENTE PRONUNCIADA','LADERA','QUEBRADA'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ZONA_DISTRITO (
  id_zona       INT          NOT NULL,
  id_distrito   INT          NOT NULL,
  PRIMARY KEY (id_zona, id_distrito),
  CONSTRAINT fk_zd_zona FOREIGN KEY (id_zona) REFERENCES ZONA (id_zona) ON DELETE CASCADE,
  CONSTRAINT fk_zd_distrito FOREIGN KEY (id_distrito) REFERENCES DISTRITO (id_distrito) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE RUTA (
  id_ruta       INT          NOT NULL,
  tipo_acceso   VARCHAR(30)  NOT NULL,
  descripcion   VARCHAR(250),
  hora_inicio   VARCHAR(5)   NOT NULL,
  hora_fin      VARCHAR(5)   NOT NULL,
  PRIMARY KEY (id_ruta)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE E_ZONA_RUTA (
  id_zona       INT          NOT NULL,
  id_ruta       INT          NOT NULL,
  PRIMARY KEY (id_zona, id_ruta),
  CONSTRAINT fk_ezr_zona FOREIGN KEY (id_zona) REFERENCES ZONA (id_zona),
  CONSTRAINT fk_ezr_ruta FOREIGN KEY (id_ruta) REFERENCES RUTA (id_ruta)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE CONTENEDOR (
  id_contenedor  INT          NOT NULL,
  tipo           VARCHAR(30)  NOT NULL,
  capacidad      INT          NOT NULL,
  estado         VARCHAR(20)  NOT NULL,
  ubicacion      VARCHAR(150),
  id_ruta        INT          NOT NULL,
  PRIMARY KEY (id_contenedor),
  UNIQUE KEY uq_cont_ruta (id_ruta, id_contenedor),
  CONSTRAINT fk_cont_ruta FOREIGN KEY (id_ruta) REFERENCES RUTA (id_ruta),
  CONSTRAINT ck_cont_estado CHECK (estado IN ('BUENO','REGULAR','MALO','EN REPARACION')),
  CONSTRAINT ck_cont_cap CHECK (capacidad > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE EMPLEADO (
  ci             INT           NOT NULL,
  nombre         VARCHAR(40)   NOT NULL,
  paterno        VARCHAR(30)   NOT NULL,
  materno        VARCHAR(30),
  fechanac       DATE          NOT NULL,
  telefono       INT,
  direccion      VARCHAR(120),
  fecha_ingreso  DATE          NOT NULL,
  salario        DECIMAL(8,2)  NOT NULL,
  genero         CHAR(1)       NOT NULL,
  PRIMARY KEY (ci),
  CONSTRAINT ck_emp_genero CHECK (genero IN ('M','F')),
  CONSTRAINT ck_emp_salario CHECK (salario >= 3300),
  CONSTRAINT ck_emp_fechas CHECK (fecha_ingreso > fechanac)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE LIMPIADOR (
  ci     INT          NOT NULL,
  turno  VARCHAR(10)  NOT NULL,
  PRIMARY KEY (ci),
  CONSTRAINT fk_limp_emp FOREIGN KEY (ci) REFERENCES EMPLEADO (ci),
  CONSTRAINT ck_limp_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE CONDUCTOR (
  ci                    INT         NOT NULL,
  vencimiento_licencia  DATE        NOT NULL,
  categoria             VARCHAR(2)  NOT NULL,
  PRIMARY KEY (ci),
  CONSTRAINT fk_cond_emp FOREIGN KEY (ci) REFERENCES EMPLEADO (ci),
  CONSTRAINT ck_cond_cat CHECK (categoria IN ('A','B','C'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE AYUDANTE (
  ci     INT          NOT NULL,
  turno  VARCHAR(10)  NOT NULL,
  PRIMARY KEY (ci),
  CONSTRAINT fk_ayud_emp FOREIGN KEY (ci) REFERENCES EMPLEADO (ci),
  CONSTRAINT ck_ayud_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE INSUMO (
  id_insumo    INT           NOT NULL,
  nombre       VARCHAR(60)   NOT NULL,
  descripcion  VARCHAR(200),
  cantidad     INT           NOT NULL,
  PRIMARY KEY (id_insumo),
  CONSTRAINT ck_ins_cant CHECK (cantidad >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ENTREGA (
  id_insumo  INT   NOT NULL,
  ci         INT   NOT NULL,
  fecha      DATE  NOT NULL,
  cantidad   INT   NOT NULL,
  PRIMARY KEY (id_insumo, ci, fecha),
  CONSTRAINT fk_ent_insumo FOREIGN KEY (id_insumo) REFERENCES INSUMO (id_insumo),
  CONSTRAINT fk_ent_emp FOREIGN KEY (ci) REFERENCES EMPLEADO (ci),
  CONSTRAINT ck_ent_cant CHECK (cantidad > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE CENTRO_DESTINO (
  id_centro    INT           NOT NULL,
  nombre       VARCHAR(80)   NOT NULL,
  descripcion  VARCHAR(200),
  telefono     INT,
  tipo         VARCHAR(30)   NOT NULL,
  direccion    VARCHAR(120),
  PRIMARY KEY (id_centro)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE VEHICULO (
  id_vehiculo  INT           NOT NULL,
  placa        VARCHAR(8)    NOT NULL,
  tipo         VARCHAR(40)   NOT NULL,
  modelo       VARCHAR(40)   NOT NULL,
  anio         INT           NOT NULL,
  capacidad    DECIMAL(5,2)  NOT NULL,
  estado       VARCHAR(20)   NOT NULL,
  id_centro    INT           NOT NULL,
  PRIMARY KEY (id_vehiculo),
  UNIQUE KEY uq_vehiculo_placa (placa),
  CONSTRAINT fk_veh_centro FOREIGN KEY (id_centro) REFERENCES CENTRO_DESTINO (id_centro),
  CONSTRAINT ck_veh_estado CHECK (estado IN ('OPERATIVO','EN MANTENIMIENTO','FUERA DE SERVICIO')),
  CONSTRAINT ck_veh_anio CHECK (anio BETWEEN 1990 AND 2030)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE E_LIM_RUTA (
  ci       INT          NOT NULL,
  id_ruta  INT          NOT NULL,
  fecha    DATE         NOT NULL,
  turno    VARCHAR(10)  NOT NULL,
  PRIMARY KEY (ci, id_ruta, fecha, turno),
  CONSTRAINT fk_elr_limp FOREIGN KEY (ci) REFERENCES LIMPIADOR (ci),
  CONSTRAINT fk_elr_ruta FOREIGN KEY (id_ruta) REFERENCES RUTA (id_ruta),
  CONSTRAINT ck_elr_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE CONDUCE (
  ci           INT          NOT NULL,
  id_vehiculo  INT          NOT NULL,
  fecha        DATE         NOT NULL,
  turno        VARCHAR(10)  NOT NULL,
  PRIMARY KEY (ci, id_vehiculo, fecha, turno),
  CONSTRAINT fk_cdc_cond FOREIGN KEY (ci) REFERENCES CONDUCTOR (ci),
  CONSTRAINT fk_cdc_veh FOREIGN KEY (id_vehiculo) REFERENCES VEHICULO (id_vehiculo),
  CONSTRAINT ck_cdc_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ASIGNA_AYUDANTE (
  ci           INT          NOT NULL,
  id_vehiculo  INT          NOT NULL,
  fecha        DATE         NOT NULL,
  turno        VARCHAR(10)  NOT NULL,
  PRIMARY KEY (ci, id_vehiculo, fecha, turno),
  CONSTRAINT fk_asa_ayud FOREIGN KEY (ci) REFERENCES AYUDANTE (ci),
  CONSTRAINT fk_asa_veh FOREIGN KEY (id_vehiculo) REFERENCES VEHICULO (id_vehiculo),
  CONSTRAINT ck_asa_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ABARCA (
  id_ruta        INT          NOT NULL,
  id_contenedor  INT          NOT NULL,
  id_vehiculo    INT          NOT NULL,
  fecha          DATE         NOT NULL,
  turno          VARCHAR(10)  NOT NULL,
  PRIMARY KEY (id_ruta, id_contenedor, id_vehiculo, fecha, turno),
  CONSTRAINT fk_abarca_cont_id FOREIGN KEY (id_contenedor) REFERENCES CONTENEDOR (id_contenedor),
  CONSTRAINT fk_abarca_cont FOREIGN KEY (id_ruta, id_contenedor) REFERENCES CONTENEDOR (id_ruta, id_contenedor),
  CONSTRAINT fk_abarca_veh FOREIGN KEY (id_vehiculo) REFERENCES VEHICULO (id_vehiculo),
  CONSTRAINT ck_abarca_turno CHECK (turno IN ('MANANA','TARDE','NOCHE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE test_conexion (
  id INT AUTO_INCREMENT PRIMARY KEY,
  mensaje VARCHAR(100),
  fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

COMMIT;
